// Depois: responsabilidades separadas e injetadas
class PedidoServiceRefatorado {
    private final PedidoRepository repository;
    private final GeradorNotaFiscal notaFiscal;
    private final Notificador notificador;

    void finalizar(Pedido p) {
        repository.save(p);
        notaFiscal.gerar(p);
        notificador.pedidoFinalizado(p);
    }
}

