interface CalculoDesconto {
    BigDecimal aplicar(BigDecimal valor);
}

@Component("BLACK_FRIDAY")
class DescontoBlackFriday implements CalculoDesconto {
    public BigDecimal aplicar(BigDecimal v) { return v.multiply(new BigDecimal("0.70")); }
}

@Component("NENHUM")
class SemDesconto implements CalculoDesconto {
    public BigDecimal aplicar(BigDecimal v) { return v; }
}

@Service
class PrecoService {
    private final Map<String, CalculoDesconto> estrategias;
    PrecoService(Map<String, CalculoDesconto> estrategias) { this.estrategias = estrategias; }

    BigDecimal preco(BigDecimal valor, String campanha) {
        return estrategias.getOrDefault(campanha, estrategias.get("NENHUM")).aplicar(valor);
    }
}

