public record Dinheiro(BigDecimal valor, Currency moeda) {
    public static Dinheiro reais(String valor) {
        return new Dinheiro(new BigDecimal(valor), Currency.getInstance("BRL"));
    }
}

// Adapter: SDK externo atrás de uma interface do domínio
class StripeGatewayAdapter implements GatewayPagamento {
    private final StripeClient stripe;
    public Recibo cobrar(Pedido p) {
        var charge = stripe.charges().create(p.totalEmCentavos(), "brl");
        return new Recibo(charge.getId());
    }
}

// Decorator: adiciona log mantendo a interface
class GatewayComLog implements GatewayPagamento {
    private final GatewayPagamento delegate;
    public Recibo cobrar(Pedido p) {
        log.info("Cobrando pedido {}", p.id());
        return delegate.cobrar(p);
    }
}

public record PedidoPago(Long pedidoId) {}

@Service
class PagamentoService {
