public class Pedido {
    private StatusPedido status;

    public void cancelar() {
        if (status == StatusPedido.ENVIADO) {
            throw new IllegalStateException("Pedido já enviado não pode ser cancelado");
        }
        status = StatusPedido.CANCELADO;
    }
}
